<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { ArrowLeft, CheckCircle2, ExternalLink, Loader2, Play, Rocket, ShieldCheck } from 'lucide-vue-next'
import { apiUrl, ensureOk } from '../lib/api'
interface Version { id:string;number:number;name:string;fileCount:number;createdAt:string }
interface Gate { gate:string;status:'pending'|'passed'|'failed';trusted:boolean;source:string;observedAt:string }
interface Preview { id:string;url:string;status:string;expiresAt:string;versionId:string }
interface Deployment { id:string;environment:string;status:string;externalUrl?:string;error?:string;updatedAt:string }
const route=useRoute();const projectId=computed(()=>String(route.params.id??''));const versions=ref<Version[]>([]);const selectedVersionId=ref('');const gates=ref<Gate[]>([]);const readyForProduction=ref(false);const previews=ref<Preview[]>([]);const deployments=ref<Deployment[]>([]);const busy=ref('');const error=ref('')
async function json(path:string,init?:RequestInit){const headers=new Headers(init?.headers);if(init?.body)headers.set('content-type','application/json');return(await(await ensureOk(await fetch(apiUrl(path),{...init,credentials:'include',headers}))).json())as any}
async function load(){error.value='';try{const versionResult=await json(`/api/engineering-projects/${projectId.value}/versions`);versions.value=versionResult.versions??[];if(!selectedVersionId.value&&versions.value.length)selectedVersionId.value=versions.value.at(-1)!.id;const[previewResult,deploymentResult]=await Promise.all([json(`/api/delivery/previews?projectId=${encodeURIComponent(projectId.value)}`),json(`/api/delivery/deployments?projectId=${encodeURIComponent(projectId.value)}`)]);previews.value=previewResult.previews??[];deployments.value=deploymentResult.deployments??[]}catch(cause){error.value=cause instanceof Error?cause.message:'加载交付状态失败'}}
async function loadGates(){if(!selectedVersionId.value){gates.value=[];readyForProduction.value=false;return}try{const result=await json(`/api/delivery/gates/${projectId.value}/${selectedVersionId.value}`);gates.value=result.evidence??[];readyForProduction.value=Boolean(result.readyForProduction)}catch(cause){error.value=cause instanceof Error?cause.message:'加载发布门禁失败'}}
async function createPreview(){if(!selectedVersionId.value)return;busy.value='preview';try{await json('/api/delivery/previews',{method:'POST',body:JSON.stringify({projectId:projectId.value,versionId:selectedVersionId.value})});await load()}catch(cause){error.value=cause instanceof Error?cause.message:'创建预览失败'}finally{busy.value=''}}
async function startRun(){busy.value='run';try{await json('/api/runs',{method:'POST',body:JSON.stringify({projectId:projectId.value,stack:'hono-drizzle',action:'verify'})})}catch(cause){error.value=cause instanceof Error?cause.message:'Runner 未启用或启动失败'}finally{busy.value=''}}
async function deploy(environment:'staging'|'production'){if(!selectedVersionId.value)return;busy.value=environment;try{await json('/api/delivery/deployments',{method:'POST',body:JSON.stringify({projectId:projectId.value,versionId:selectedVersionId.value,environment})});await load()}catch(cause){error.value=cause instanceof Error?cause.message:'部署未启动'}finally{busy.value=''}}
function openPreview(preview:Preview){window.open(apiUrl(preview.url),'_blank','noopener,noreferrer')}
watch(selectedVersionId,()=>void loadGates());onMounted(async()=>{await load();await loadGates()})
</script>
<template><main class="min-h-[calc(100vh-4rem)] pt-20 pb-16"><div class="mx-auto max-w-6xl px-4 sm:px-6 lg:px-8"><RouterLink :to="`/projects/${projectId}`" class="inline-flex items-center gap-2 text-sm text-mut hover:text-ink"><ArrowLeft class="h-4 w-4" />返回项目</RouterLink><header class="mt-5"><p class="text-xs font-semibold text-brand1">Engineering Delivery</p><h1 class="mt-2 text-3xl font-bold text-ink">预览、部署与发布门禁</h1><p class="mt-2 text-sm text-mut">从不可变工程版本创建隔离预览；生产部署只接受可信且完整的质量证据。</p></header><p v-if="error" class="mt-5 rounded-xl border border-red-500/25 bg-red-500/5 p-3 text-sm text-red-500">{{ error }}</p><section class="mt-6 rounded-3xl border border-line/10 bg-soft/60 p-5 sm:p-7"><label class="text-xs font-semibold text-sub">工程版本<select v-model="selectedVersionId" class="mt-2 w-full rounded-xl border border-line/10 bg-app px-3 py-3 text-sm text-ink"><option value="">请选择版本</option><option v-for="version in versions" :key="version.id" :value="version.id">v{{ version.number }} · {{ version.name }} · {{ version.fileCount }} 文件</option></select></label><div class="mt-5 flex flex-wrap gap-3"><button :disabled="!selectedVersionId || Boolean(busy)" class="rounded-xl border border-line/10 px-4 py-2.5 text-sm font-semibold text-ink disabled:opacity-40" @click="startRun"><Loader2 v-if="busy === 'run'" class="mr-2 inline h-4 w-4 animate-spin" /><Play v-else class="mr-2 inline h-4 w-4" />运行验证</button><button :disabled="!selectedVersionId || Boolean(busy)" class="rounded-xl border border-line/10 px-4 py-2.5 text-sm font-semibold text-ink disabled:opacity-40" @click="createPreview"><Loader2 v-if="busy === 'preview'" class="mr-2 inline h-4 w-4 animate-spin" /><ExternalLink v-else class="mr-2 inline h-4 w-4" />创建在线预览</button><button :disabled="!selectedVersionId || Boolean(busy)" class="rounded-xl border border-line/10 px-4 py-2.5 text-sm font-semibold text-ink disabled:opacity-40" @click="deploy('staging')">部署到 Staging</button><button :disabled="!selectedVersionId || !readyForProduction || Boolean(busy)" class="bg-brand-gradient rounded-xl px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-40" @click="deploy('production')"><Rocket class="mr-2 inline h-4 w-4" />部署到 Production</button></div></section><div class="mt-6 grid gap-6 lg:grid-cols-2"><section class="rounded-3xl border border-line/10 bg-soft/60 p-5"><h2 class="flex items-center gap-2 font-semibold text-ink"><ShieldCheck class="h-5 w-5 text-brand1" />发布门禁</h2><div class="mt-4 grid gap-2"><div v-for="gate in gates" :key="gate.gate" class="flex items-center justify-between rounded-xl border border-line/10 bg-app/50 px-3 py-2 text-xs"><span class="font-mono text-sub">{{ gate.gate }}</span><span :class="gate.status === 'passed' && gate.trusted ? 'text-emerald-600' : gate.status === 'failed' ? 'text-red-500' : 'text-faint'">{{ gate.status }}{{ gate.trusted ? ' · trusted' : '' }}</span></div></div><p class="mt-3 text-xs" :class="readyForProduction ? 'text-emerald-600' : 'text-amber-600'">{{ readyForProduction ? '全部可信门禁通过，可以生产部署。' : '生产部署已锁定，等待 CI／Runner 可信证据。' }}</p></section><section class="rounded-3xl border border-line/10 bg-soft/60 p-5"><h2 class="font-semibold text-ink">在线预览</h2><div class="mt-4 grid gap-2"><button v-for="preview in previews" :key="preview.id" class="flex items-center justify-between rounded-xl border border-line/10 bg-app/50 px-3 py-3 text-left text-xs" @click="openPreview(preview)"><span><strong class="block text-ink">{{ preview.status }}</strong><small class="text-faint">到期 {{ preview.expiresAt }}</small></span><ExternalLink class="h-4 w-4 text-brand1" /></button><p v-if="!previews.length" class="text-xs text-faint">尚未创建在线预览。</p></div></section></div><section class="mt-6 rounded-3xl border border-line/10 bg-soft/60 p-5"><h2 class="font-semibold text-ink">部署记录</h2><div class="mt-4 grid gap-2"><div v-for="item in deployments" :key="item.id" class="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-line/10 bg-app/50 px-3 py-3 text-xs"><span><strong class="text-ink">{{ item.environment }} · {{ item.status }}</strong><small class="ml-2 text-faint">{{ item.updatedAt }}</small></span><a v-if="item.externalUrl" :href="item.externalUrl" target="_blank" rel="noopener noreferrer" class="text-brand1">打开部署</a><span v-else-if="item.error" class="text-red-500">{{ item.error }}</span><CheckCircle2 v-else class="h-4 w-4 text-faint" /></div><p v-if="!deployments.length" class="text-xs text-faint">尚无部署记录。</p></div></section></div></main></template>
